{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments, which may suggest risk for immune-related adverse events (irAEs). The following are not exclusionary: vitiligo, childhood asthma that has resolved, type 1 diabetes, residual hypothyroidism that required only hormone replacement, or psoriasis that does not require systemic treatment.",
      "quote": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments, which may suggest risk for immune-related adverse events (irAEs).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with an agent that blocks the PD-1/PD-L1 pathway.",
      "quote": "Prior treatment with an agent that blocks the PD-1/PD-L1 pathway",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with other systemic immune-modulating agents within fewer than 28 days prior to the first dose of cemiplimab. Examples include therapeutic vaccines, cytokine treatments, or agents that target CTLA-4, 4-1BB (CD137), or OX-40. Prior treatment with imiquimod or other topical or intralesional immune modulators will not be exclusionary.",
      "quote": "Prior treatment with other systemic immune-modulating agents within fewer than 28 days prior to the first dose of cemiplimab.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Untreated brain metastasis(es) that may be considered active. Patients with previously treated brain metastases may participate if stable for at least 6 weeks on imaging, no new or enlarging metastases, and no immunosuppressive doses of systemic corticosteroids within 28 days of first dose. Patients with brain involvement of BCC due to direct extension may be allowed if not requiring >10 mg prednisone daily, after medical monitor approval.",
      "quote": "Untreated brain metastasis(es) that may be considered active.",
      "thresholds": [
        {
          "test": "prednisone",
          "op": ">",
          "value": 10,
          "unit": "mg daily"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of cemiplimab. Patients who require brief courses of steroids (e.g., as prophylaxis for imaging studies due to hypersensitivity to contrast agents) are not excluded.",
      "quote": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of cemiplimab",
      "thresholds": [
        {
          "test": "prednisone",
          "op": ">",
          "value": 10,
          "unit": "mg daily"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Active infection requiring therapy, including positive tests for HIV-1 or HIV-2 serum antibody, hepatitis B virus (HBV), or hepatitis C virus (HCV).",
      "quote": "Active infection requiring therapy, including positive tests for human immunodeficiency virus (HIV)-1 or HIV-2 serum antibody, hepatitis B virus (HBV), or hepatitis C virus (HCV)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of pneumonitis within the last 5 years.",
      "quote": "History of pneumonitis within the last 5 years",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any anticancer treatment other than radiation therapy (chemotherapy, targeted systemic therapy, imiquimod, photodynamic therapy), investigational or standard of care, within 30 days of initial administration of cemiplimab or planned during study. Patients receiving bisphosphonates or denosumab allowed. Patients excluded if receive radiation therapy within ≤14 days of initial administration or planned during study.",
      "quote": "Any anticancer treatment other than radiation therapy (chemotherapy, targeted systemic therapy, imiquimod, photodynamic therapy), investigational or standard of care, within 30 days of the initial administration of cemiplimab or planned to occur during the study period",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments.",
      "quote": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with allergy or hypersensitivity to cemiplimab or to any of the excipients must be excluded.",
      "quote": "Patients with allergy or hypersensitivity to cemiplimab or to any of the excipients must be excluded.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Concurrent malignancy other than BCC and/or history of malignancy other than BCC within 3 years of first planned dose, except for tumors with negligible risk of metastasis or death, such as adequately treated CSCC of the skin, carcinoma in situ of the cervix, or ductal carcinoma in situ of the breast, or low-risk early stage prostate adenocarcinoma (T1-T2a N0M0 and Gleason score <6 and PSA <10 ng/mL) for which management is active surveillance, or prostate adenocarcinoma with biochemical-only recurrence with documented PSA doubling time >12 months for which management is active surveillance. Patients with hematologic malignancies (e.g., chronic lymphocytic leukemia) are excluded.",
      "quote": "Concurrent malignancy other than BCC and/or history of malignancy other than BCC within 3 years of date of first planned dose of cemiplimab",
      "thresholds": [
        {
          "test": "PSA",
          "op": "<",
          "value": 10,
          "unit": "ng/mL"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation.",
      "quote": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a history of solid organ transplant (patients with prior corneal transplants may be allowed to enroll after discussion with and approval from the medical monitor).",
      "quote": "Patients with a history of solid organ transplant",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any medical co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation in a clinical trial due to high safety risks and/or potential to affect interpretation of results of the study.",
      "quote": "Any medical co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation in a clinical trial due to high safety risks and/or potential to affect interpretation of results of the study",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Inability to undergo any contrast-enhanced radiologic response assessment. A patient unable to undergo CT with iodinated contrast would not be excluded if disease can be measured by MRI with gadolinium. A patient unable to undergo MRI with gadolinium would not be excluded if disease can be measured by CT with contrast. For Group 2, if unable to undergo any contrast-enhanced imaging, may be eligible if disease can be assessed with digital medical photography, after medical monitor approval.",
      "quote": "Inability to undergo any contrast-enhanced radiologic response assessment",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Breastfeeding.",
      "quote": "Breastfeeding",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Positive serum pregnancy test (a false positive pregnancy test, if demonstrated by serial measurements and negative ultrasound, will not be exclusionary, upon communication with and approval from the medical monitor).",
      "quote": "Positive serum pregnancy test",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Receipt of live vaccines (including attenuated) within 30 days of first study treatment.",
      "quote": "Receipt of live vaccines (including attenuated) within 30 days of first study treatment",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Women of childbearing potential (WOCBP), or sexually active men, who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 6 months after the last dose. Highly effective contraceptive measures include: stable use of combined hormonal contraception, progestogen-only hormonal contraception, IUD, IUS, bilateral tubal ligation, vasectomized partner, and/or sexual abstinence. Periodic abstinence, withdrawal, spermicides only, and lactational amenorrhoea method are not acceptable. Female condom and male condom should not be used together.",
      "quote": "Women of childbearing potential (WOCBP)*, or sexually active men, who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 6 months after the last dose.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with idelalisib.",
      "quote": "Prior treatment with idelalisib",
      "thresholds": []
    }
  ]
}
